def is_magic(seq):
    n = len(seq)
    for i in range(n):
        if seq.count(i) != seq[i]:
            return False
    return True

def search_magic(n):
    # Constraints:
    # sum(x) = n
    # sum(i * x[i]) = n  (double counting argument)
    # x[i] >= 0

    # For n=16, x[0] is typically around 12
    # Known pattern: x[0]=n-4, x[2]=2, x[n-4]=1, x[n-3] doesn't work simply
    # Let me try the known answer for n=16 directly

    # For magic sequences, known solutions exist for n=4,7 and all n>=7
    # Pattern: x[0]=n-4, x[2]=2, x[n-4]=1, rest=0... let's verify

    # Try systematic search with constraints
    for x0 in range(n, -1, -1):
        for x1 in range(n - x0 + 1):
            for x2 in range(n - x0 - x1 + 1):
                for x3 in range(n - x0 - x1 - x2 + 1):
                    # Check weighted sum constraint with remaining all zeros
                    # weighted = 0*x0 + 1*x1 + 2*x2 + 3*x3 + higher terms
                    # If rest are 0, weighted = x1 + 2*x2 + 3*x3
                    # But we might need one more non-zero term

                    base_sum = x0 + x1 + x2 + x3
                    base_weighted = x1 + 2*x2 + 3*x3

                    if base_sum > n:
                        break

                    remaining = n - base_sum
                    remaining_weighted = n - base_weighted

                    if remaining_weighted < 0:
                        break

                    if remaining == 0 and remaining_weighted == 0:
                        seq = [x0, x1, x2, x3] + [0] * (n - 4)
                        if is_magic(seq):
                            return seq
                    elif remaining > 0 and remaining_weighted > remaining:
                        # One more term: x[k] = remaining at position k
                        # k * remaining = remaining_weighted - 0 (rest are 0)
                        # Actually: k * remaining = remaining_weighted
                        if remaining_weighted % remaining == 0:
                            k = remaining_weighted // remaining
                            if 4 <= k < n:
                                seq = [x0, x1, x2, x3] + [0] * (n - 4)
                                seq[k] = remaining
                                if is_magic(seq):
                                    return seq
    return None

result = search_magic(16)
print("Result:", result)
if result:
    print("Is magic:", is_magic(result))
    print("\nVerification:")
    for i, v in enumerate(result):
        cnt = result.count(i)
        status = "✓" if cnt == v else "✗"
        if v != 0 or cnt != 0:
            print(f"  {status} x[{i}] = {v}, count of {i} = {cnt}")
